INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3773, 'ស្ពានមួយមានកំពូលខ្ពស់ពីផ្ទៃទឹក \(6\ \text{m}\) ហើយឆ្លុះជារូបក្នុងទឹក។ ក. ចម្ងាយពីកំពូលស្ពានដល់កំពូលរូបឆ្លុះប៉ុន្មាន? ខ. បើស្ពានខ្ពស់ \(9\ \text{m}\) ចម្ងាយប៉ុន្មាន? គ. ផ្ទៃទឹកដើរតួជាអ្វីសម្រាប់ការឆ្លុះ?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(2 \times 6 = 12\ \text{m}\) (2 ពិន្ទុ)
