INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3775, 'អ្នករចនាធ្វើស្លាកសញ្ញារាងត្រីកោណសម័ង្សមួយ ក្នុងរង្វង់មួយ។ ក. ស្លាកសញ្ញាមានអ័ក្សឆ្លុះប៉ុន្មាន? ខ. អ័ក្សនីមួយៗកាត់តាមអ្វី? គ. បើដាក់ស្លាក \(3\) ស្មើគ្នាជុំវិញរង្វង់ ចំនួនអ័ក្សឆ្លុះសរុប?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(3\) អ័ក្សឆ្លុះ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 3776, 'នៅមាត់បឹង ដើមឈើកម្ពស់ \(15\ \text{m}\) ឆ្លុះក្នុងទឹកស្ងប់។ ក. កំពូលរូបឆ្លុះនៅក្រោមផ្ទៃទឹកប៉ុន្មាន? ខ. ចម្ងាយពីកំពូលទៅកំពូលរូបឆ្លុះ? គ. បើបឹងមានរលក តើរូបឆ្លុះមានអ្វីប្រែប្រួល?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(15\ \text{m}\) ក្រោមផ្ទៃទឹក (1 ពិន្ទុ)
